#!/usr/bin/env python3
"""make_cf_preview.py -- PREVIEW ONLY. Builds dist/ABC_cardface_preview.html from your src + assets with the
archetype strip, evolution drag and new card back applied in memory. src/ and assets/ are not touched.

Run from the repo root:   python3 make_cf_preview.py
Then open dist/ABC_cardface_preview.html.
"""
import os, sys, re, json
JS = r'''/* fix_cardface_evolve */
/* fix_cardface_evolve: printed-card HP + archetype strip on the board's Active card, drag an evolution card onto
   the character it evolves from, and the new card back. */

/* ---------- 1. HP + archetype down the right-hand strip, like the printed card ---------- */
function abcPfStrip(ch){
  try{ if(!ch || !abcPfCls(ch)) return ''; }catch(e){ return ''; }
  const hp=ch.maxHp||ch.hp||'', arch=ch.archetype||'';
  return '<div class="pcz-hp pfs-hp"><b style="--hfs:'+(String(hp).length<3?8.2:7.4)+'cqw">'+hp+'</b><small>HP</small></div>'
    +(arch?'<div class="pcz-arch pfs-arch"><span style="--afs:'+abcPcFit(arch,36,9.2,.52).toFixed(2)+'cqw">'+abcPfEsc(arch)+'</span></div>':'');
}

/* ---------- 2. evolution cards: drag onto the character they evolve from ---------- */
const ABC_EVO={ uid:null };
const abcDdKindEvo=abcDdKind;
abcDdKind=function(c){ if(c && c.cat==='act') return 'act'; return abcDdKindEvo(c); };
const abcDdTargetsEvo=abcDdTargets;
abcDdTargets=function(kind,card){
  if(kind!=='act') return abcDdTargetsEvo(kind,card);
  const out=[], P=S.you, a=actById(card&&card.actId); if(!a) return out;
  actTargets(P,a).forEach(function(c){
    const el=document.querySelector('#game .char.you[data-charuid="'+c.uid+'"]') || document.querySelector('#game .bench-mini[data-benchinfo="you:'+c.uid+'"]'); if(!el) return;
    const r=actCanEvolve(c,a), nm=abcDdShort(c.name);
    out.push({el:el, uid:c.uid, label:r.ok?('Evolve '+nm+' → '+a.name):(r.why||'Not yet'), short:r.ok?'★':'✕', no:!r.ok});
  });
  return out;
};
const abcDdActEvo=abcDdAct;
abcDdAct=function(idx,kind,z){
  if(kind!=='act') return abcDdActEvo(idx,kind,z);
  const c=S.you.hand[idx]; if(!c || c!==ABC_DD.card) return;
  ABC_EVO.uid=z.uid; try{ tryPlayHandCard(idx); } finally{ ABC_EVO.uid=null; }
};
/* the dropped-on character is the one that evolves (when it is eligible) */
const abcActPickEvo=actPick;
actPick=function(p,card){
  const r=abcActPickEvo(p,card);
  if(ABC_EVO.uid && r && r.a && p===S.you){
    const c=p.team.find(function(x){ return x.uid===ABC_EVO.uid; });
    if(c && actTargets(p,r.a).indexOf(c)>=0 && actCanEvolve(c,r.a).ok) return {a:r.a, t:c, why:''};
  }
  return r;
};
/* dropping on a red (not-yet) zone says why, instead of silently returning the card */
const abcDdEndEvo=abcDdEnd;
abcDdEnd=function(drop){ if(drop && drop.no && ABC_DD.on){ try{ toast(drop.label,'bad'); }catch(e){} } return abcDdEndEvo(drop); };
if(typeof window!=='undefined') window.ABC_CF={ strip:abcPfStrip, evo:ABC_EVO };
'''
CSS = r"""
/* fix_cardface_evolve */
/* HP + archetype strip: only on framed Active cards on the arena board (same geometry as the printed card) */
.pfs-hp,.pfs-arch{display:none}
body.abc-arena[data-screen="play"] .side .char.pf .pfs-hp{display:flex;pointer-events:none}
body.abc-arena[data-screen="play"] .side .char.pf .pfs-arch{display:flex;pointer-events:none}
body.abc-arena[data-screen="play"] .side .char.pf.pf-fe .pfs-hp,
body.abc-arena[data-screen="play"] .side .char.pf.pf-fe .pfs-arch span{color:#fff;text-shadow:0 .3cqw 1cqw #000}
/* new card back: the art carries its own black rounded border */
.cardback:has(> .cb-img){background:#f3ead6!important;border:0!important;box-shadow:0 1px 0 rgba(0,0,0,.35)!important;border-radius:6px}
.cardback > .cb-img,.cardback.top > .cb-img{position:absolute;inset:0!important;width:100%!important;height:100%!important;object-fit:fill;border:0!important;border-radius:inherit}
/* the stacked edges under the top card match it: cream card stock, black rim */
.deckstack .cardback.edge{background:#efe5cf!important;border:2px solid #111!important;box-shadow:none!important;border-radius:6px}
.hc.dm-fd .cb-img,.fly-card .cb-img{object-fit:fill!important;border:0!important}
"""
BACK = ''

SRC=os.path.join('src','game.src.html'); ASSETS=os.path.join('assets','assets.json'); MARK='/* fix_cardface_evolve */'
OLD_BACK='window.CARD_BACK="data:image/jpeg;base64,__ABCASSET_956__";'
PIPS='    <div class="pips">${chargePips(ch)}</div>\n    <div class="pc-moves">'
def apply(s, assets, TAG):
    if MARK in s: sys.exit(f'{TAG} Already applied -- nothing to do.')
    for need,who in [('/* fix_dragdrop_cards */','fix_dragdrop_cards.py'),('function abcPcFit(','fix_print_cards.py'),('function actPick(','three-act evolution')]:
        if need not in s: sys.exit(f'{TAG} ERROR: run {who} first. Nothing written.')
    for l,a in [('end of <head> styles',"</style>\n</head>"),('JS insertion point',"function menuScreen(){\n"),('Active card markup',PIPS),('card back',OLD_BACK)]:
        if s.count(a)!=1: sys.exit(f'{TAG} ERROR: anchor "{l}" found {s.count(a)} times (expected 1). Nothing written.')
    used={int(x) for x in re.findall(r'__ABCASSET_(\d+)__', s)} | {int(k[1:]) for k in assets if k[1:].isdigit()}
    nid=max(used)+1
    s=s.replace("</style>\n</head>",CSS+"</style>\n</head>",1)
    s=s.replace("function menuScreen(){\n",JS+"\nfunction menuScreen(){\n",1)
    s=s.replace(PIPS,'    ${abcPfStrip(ch)}   <!-- fix_cardface_evolve -->\n'+PIPS,1)
    s=s.replace(OLD_BACK,'window.CARD_BACK="data:image/webp;base64,__ABCASSET_%d__";   /* fix_cardface_evolve: new card back (was a956) */' % nid,1)
    for need in [MARK,'${abcPfStrip(ch)}','function abcPfStrip(','__ABCASSET_%d__' % nid]:
        if need not in s: sys.exit(f'{TAG} ERROR: post-check failed ({need}). Nothing written.')
    return s, nid

TAG='[cf_preview]'
if not os.path.exists(SRC): sys.exit(f'{TAG} ERROR: run from the repo root (src/game.src.html not found).')
assets=json.load(open(ASSETS,encoding='utf-8'))
s,nid=apply(open(SRC,encoding='utf-8').read(),assets,TAG)
assets=dict(assets); assets['a%d' % nid]=BACK
out=re.sub(r'__ABCASSET_(\d+)__',lambda m:assets['a'+m.group(1)],s)
os.makedirs('dist',exist_ok=True); p=os.path.join('dist','ABC_cardface_preview.html'); open(p,'w',encoding='utf-8').write(out)
print(f'{TAG} wrote',p,f'({len(out):,} bytes) -- src/ and assets/ untouched.')
